function drawRewards(){const lv=playerLevel(),labels={title:'稱號',back:'牌背',dino:'小恐龍配色',avatar:'聊天室頭像'};let html=`<div class="reward-summary"><strong>Lv. ${lv} · ${playerTitle().name}</strong><p>達到等級就永久開放。選一個外觀，下一局就會用上。</p></div>`;for(let kind of Object.keys(rewardCatalog)){html+=`<section class="reward-section"><h3>${labels[kind]}</h3>`;if(kind==='back')html+='<p>用在大老二 NPC 手牌和抽鬼牌背面；色牌背面預覽也會顯示。</p>';if(kind==='title')html+=`<button class="reward-auto ${state.appearance.title==='auto'?'chosen':''}" data-kind="title" data-reward="auto" aria-pressed="${state.appearance.title==='auto'}">自動使用最高稱號</button>`;html+='<div class="reward-grid">';for(let r of rewardCatalog[kind]){let locked=lv<r.level,selected=state.appearance[kind]===r.id;html+=`<button class="reward-item ${selected?'chosen':''}" data-kind="${kind}" data-reward="${r.id}" aria-pressed="${selected}" ${locked?'disabled':''}><span class="reward-icon ${kind==='back'?'back-preview back-'+r.id:''}">${r.icon}</span><strong>${r.name}</strong><small>${locked?'🔒 Lv. '+r.level: selected?'使用中':'已解鎖 · Lv. '+r.level}</small></button>`}html+='</div></section>'}html+=`<section class="reward-section"><h3>熟客專屬台詞</h3><p>Lv.10、20、35、50 各有新對白；吐槽與溫柔模式都有自己的版本。</p><div class="bubble">${npcLine()}</div></section>`;ui(html);$('#game').querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{let kind=b.dataset.kind,id=b.dataset.reward,r=rewardCatalog[kind].find(r=>r.id===id);if(id!=='auto'&&(!r||r.level>playerLevel()))return;state.appearance[kind]=id;persist();drawRewards();toast('已換好，下次開局就會看到！')})}
