function stop(){cleanup();cleanup=()=>{};timers.forEach(clearTimeout);timers=[]}function openGame(id){stop();active=id;let g=games.find(g=>g[0]===id);$('#gameTitle').textContent=g[2];$('#gameTag').textContent=g[4]+' / PLAYER 01';$('#modal').showModal();$('#game').innerHTML='';handlers[id]()}function closeGame(){stop();$('#modal').close();renderGrid($('.active[data-cat]')?.dataset.cat||'全部')}$('#close').onclick=closeGame;$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeGame()});$('#tone').onclick=()=>{state.gentle=!state.gentle;persist()};$('#random').onclick=()=>openGame(pick(games)[0]);$('#filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('#filters .active').classList.remove('active');b.classList.add('active');renderGrid(b.dataset.cat)});$('#logo').onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'})};$('#achievements').onclick=()=>{stop();$('#gameTitle').textContent='你的成就櫃';$('#gameTag').textContent='PLAYER RECORD';$('#game').innerHTML=achievements.map(a=>`<div class="achievement ${state.ach.includes(a[0])?'':'locked'}"><span>${state.ach.includes(a[0])?'🏆':'🔒'}</span><div><strong>${a[1]}</strong><p>${a[2]}</p></div></div>`).join('');$('#modal').showModal()};
