ghost(){let deck=shuffle([...Array.from({length:13},(_,i)=>i+1),...Array.from({length:13},(_,i)=>i+1),0]),hands=[deck.slice(0,14),deck.slice(14)],done=false;function pairs(a){let out=[];for(let x of a){let j=out.indexOf(x);if(x&&j>=0)out.splice(j,1);else out.push(x)}return out}hands=hands.map(pairs);ui('<p>自動丟掉成對的牌。點一張 NPC 背面牌抽走，最後拿著鬼牌的人輸。</p><div class="stats" id="ghostcounts"></div><div id="backs" class="cards"></div><p>你的牌</p><div id="myghost" class="cards"></div>'+resultBox+'<div class="choices"><button id="reset">重新發牌</button></div>');function draw(){$('#ghostcounts').textContent='你 '+hands[0].length+' 張 · NPC '+hands[1].length+' 張';$('#myghost').innerHTML=hands[0].map(x=>`<div class="card">${x||'👻'}</div>`).join('');$('#backs').innerHTML=hands[1].map((_,i)=>`<button class="card card-back back-${equipped('back').id}" data-i="${i}" aria-label="抽第 ${i+1} 張牌">${equipped('back').icon}</button>`).join('');$('#backs').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(done)return;let x=hands[1].splice(+b.dataset.i,1)[0];hands[0]=pairs([...hands[0],x]);if(check()){draw();return}let n=hands[0].splice(rand(hands[0].length),1)[0];hands[1]=pairs([...hands[1],n]);result('你抽到 '+(x||'👻')+' · NPC 也抽完了');check();draw()})}function check(){if(!hands[0].length||!hands[1].length){done=true;result(!hands[0].length?'你贏了！鬼牌去 NPC 家了。':'鬼牌留下來陪你了 👻');finish('',10,{outcome:!hands[0].length?'win':'lose'});return true}return false}$('#reset').onclick=()=>handlers.ghost();check();draw()},
